-- DEMO CONVENIENCE: secrets generated by the app on first start when they are
-- not provided as environment variables. Environment variables always take
-- precedence. Before a real pilot, set the secrets in the hosting provider and
-- delete these rows: the plan requires private signing keys to live outside
-- the database.
create table system_secrets (
  name text primary key,
  value text not null,
  created_at timestamptz not null default now()
);

alter table system_secrets enable row level security;
alter table system_secrets force row level security;
create policy system_only on system_secrets using (app_is_system()) with check (app_is_system());
grant select, insert on system_secrets to vimba_app;
